# ==============================================================================
# EyeCam Studio - Cyber Eye Camera Lens Icon (.ico)
# Unified with Android app icon and assets/eyecam-icon.png
# ==============================================================================
$targetDir = if ($PSScriptRoot) {
    Join-Path $PSScriptRoot "..\..\src\windows\gui"
} else {
    Join-Path (Get-Location).Path "src\windows\gui"
}
$targetDir = [System.IO.Path]::GetFullPath($targetDir)
if (-not (Test-Path $targetDir)) {
    New-Item -ItemType Directory -Path $targetDir -Force | Out-Null
}
$icoPath = Join-Path $targetDir "eyecam_pc.ico"
$b64 = ""
$icoBytes = [System.Convert]::FromBase64String($b64)
[System.IO.File]::WriteAllBytes($icoPath, $icoBytes)
$cyberIcoPath = Join-Path $targetDir "eyecam_cyber.ico"
[System.IO.File]::WriteAllBytes($cyberIcoPath, $icoBytes)
Write-Host "[EyeCam] Successfully generated $icoPath and $cyberIcoPath"
exit 0